# Insect antenna types, generated by one rule set (wikibio.zoomorph.antenna). Every insect antenna has
# three parts: the scape (basal segment, with the muscles that move the antenna), the pedicel (containing
# Johnston's organ) and the flagellum, whose subdivisions (flagellomeres) lack intrinsic muscles. The
# types differ only in the shape and number of flagellomeres: thread-like (filiform), tapering
# (setaceous), bead-like (moniliform), saw-toothed (serrate), gradually or abruptly clubbed (clavate,
# capitate), comb-like (pectinate), feathery (plumose; hearing in male mosquitoes), with plate-like
# terminal lamellae (lamellate; scarabs), elbowed after a long scape (geniculate), or reduced to an
# enlarged postpedicel carrying a bristle, the arista (aristate; cyclorrhaphan flies). Colours: scape
# yellow, pedicel orange, flagellum blue. Examples are typical groups, not exclusive ones.
import wikibio as bio
from wikibio import zoomorph as zm

P = bio.P
fig, ax = bio.canvas(24, 18.6)
CW, CH = 6.0, 6.0
CELLS = [
    ("parts", "Parts of an antenna", ""),
    ("filiform", "Filiform", "Ground beetles"),
    ("setaceous", "Setaceous", "Dragonflies, cicadas"),
    ("moniliform", "Moniliform", "Termites"),
    ("serrate", "Serrate", "Click beetles"),
    ("clavate", "Clavate", "Butterflies, ladybirds"),
    ("capitate", "Capitate", "Sap beetles"),
    ("pectinate", "Pectinate", "Fire-coloured beetles"),
    ("plumose", "Plumose", "Male mosquitoes, midges"),
    ("lamellate", "Lamellate", "Scarab beetles"),
    ("geniculate", "Geniculate", "Ants, weevils, honey bees"),
    ("aristate", "Aristate", "House flies, Drosophila"),
]
LEN = {"aristate": 2.0, "lamellate": 3.2, "plumose": 3.8, "pectinate": 3.8, "capitate": 3.4, "moniliform": 3.8}
ANG = {"geniculate": 62, "aristate": 70, "lamellate": 80, "pectinate": 82}
for i, (kind, title, ex) in enumerate(CELLS):
    col, row = i % 4, i // 4
    x0, y0 = col * CW, 18.6 - (row + 1) * CH
    bio.label(ax, (x0 + 0.3, y0 + CH - 0.35), title, size="normal", bold=True, ha="left")
    if ex:
        bio.label(ax, (x0 + 0.3, y0 + CH - 0.85), ex, size="tiny", ha="left", color=P.muted())
    base = (x0 + 2.2, y0 + 0.55)
    if kind == "parts":
        a = zm.antenna(ax, (x0 + 1.4, y0 + 0.55), 70, 4.6, "filiform", curve=-1.2)
        bio.callout(ax, a["scape"], (x0 + 3.0, y0 + 0.75), "Scape", size="tiny")
        bio.callout(ax, a["pedicel"], (x0 + 3.0, y0 + 1.25), "Pedicel", size="tiny")
        bio.callout(ax, a["flagellum"], (x0 + 4.0, y0 + 2.6), "Flagellum", size="tiny")
        bio.label(ax, (x0 + 4.0, y0 + 2.2), "(flagellomeres)", size="tiny", ha="left", color=P.muted())
        continue
    a = zm.antenna(ax, base, ANG.get(kind, 78), LEN.get(kind, 4.2), kind, curve=-0.8 if kind not in ("geniculate", "aristate") else 0)
    if kind in ("clavate", "capitate"):
        bio.callout(ax, a["club"], (x0 + 4.4, a["club"][1] - 0.6), "Club", size="tiny")
    elif kind == "lamellate":
        bio.callout(ax, a["lamella"], (x0 + 4.6, a["lamella"][1] - 1.0), "Lamellae", size="tiny")
    elif kind == "geniculate":
        bio.callout(ax, a["scape"], (x0 + 3.9, y0 + 1.0), "Long scape", size="tiny")
        bio.callout(ax, a["pedicel"], (x0 + 4.2, y0 + 2.4), "Elbow", size="tiny")
    elif kind == "aristate":
        bio.callout(ax, a["arista"], (x0 + 4.5, y0 + 3.6), "Arista", size="tiny")
        bio.callout(ax, a["flagellum"], (x0 + 4.5, y0 + 1.2), "Postpedicel", size="tiny")
    elif kind == "pectinate":
        bio.callout(ax, a["branch"], (x0 + 4.3, y0 + 3.3), "Rami", size="tiny")
    elif kind == "plumose":
        bio.callout(ax, a["setae"], (x0 + 3.9, y0 + 2.6), "Setal whorls", size="tiny")
# grid lines between cells
for c in range(1, 4):
    ax.plot([c * CW, c * CW], [0.2, 18.4], color=P.muted(), lw=0.4, alpha=0.5)
for r in range(1, 3):
    ax.plot([0.2, 23.8], [r * CH + 0.6, r * CH + 0.6], color=P.muted(), lw=0.4, alpha=0.5)
